using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;using AshkanPharmacy.Core;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Forms{public partial class SalesForm:Form{TextBox scan=new TextBox();DataGridView cart=new DataGridView();Label total=new Label();List<SaleLine> lines=new List<SaleLine>(); PaymentSummary lastPayment;public SalesForm(){InitializeComponent();BackColor=Color.FromArgb(232,249,244);AutoScroll=true;PageChrome.Header(this,Localization.Persian?"صندوق فروش هوشمند":"Smart Point of Sale",Localization.Persian?"فروش سریع، کنترل موجودی و تسویه امن":"Fast checkout, stock-aware selling and secure settlement",Color.FromArgb(16,137,126),Color.FromArgb(44,89,151));Build();}void Build(){var h=new Label{Text=Localization.Persian?"فروش سریع و صندوق":"Smart Sales & POS",Left=25,Top=155,Width=500,Height=40,Font=Theme.Font(17,FontStyle.Bold),ForeColor=Theme.Navy};scan.SetBounds(25,75,500,38);scan.Font=Theme.Font(11);scan.BackColor=Color.FromArgb(246,251,250);scan.Text=Localization.Persian?"بارکد یا نام دارو...":"Barcode or medicine name...";var add=new Button{Text=Localization.Persian?"افزودن به سبد":"Add to cart",Left=540,Top=210,Width=150,Height=38,BackColor=Theme.Teal,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};add.FlatAppearance.BorderSize=0;add.Click+=(s,e)=>AddToCart();scan.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){AddToCart();e.SuppressKeyPress=true;}};var scanner=new Label{Text=Localization.Persian?"● حالت اسکنر فعال":"● SCANNER READY",Left=705,Top=210,Width=100,Height=30,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Theme.Teal,Font=Theme.Font(7,FontStyle.Bold)};cart.SetBounds(25,135,780,420);cart.AllowUserToAddRows=false;cart.ReadOnly=true;cart.SelectionMode=DataGridViewSelectionMode.FullRowSelect;Theme.StyleGrid(cart);var remove=new Button{Text=Localization.Persian?"حذف ردیف":"Remove item",Left=825,Top=135,Width=180,Height=42,BackColor=Color.FromArgb(226,55,75),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};remove.Click+=(s,e)=>Remove();total.SetBounds(825,220,260,80);total.Font=Theme.Font(18,FontStyle.Bold);total.ForeColor=Theme.Navy;var pay=new Button{Text=Localization.Persian?"ثبت و پرداخت":"Complete Sale",Left=825,Top=330,Width=230,Height=70,BackColor=Theme.Teal,ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Font=Theme.Font(12,FontStyle.Bold)};pay.FlatAppearance.BorderSize=0;pay.Click+=(s,e)=>Checkout();var hold=new Button{Text=Localization.Persian?"تعلیق فروش":"Hold sale",Left=825,Top=415,Width=110,Height=38,BackColor=Theme.Indigo,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};hold.Click+=(s,e)=>HoldSale();var resume=new Button{Text=Localization.Persian?"ادامه فروش":"Resume",Left=945,Top=415,Width=110,Height=38,BackColor=Theme.Navy,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};resume.Click+=(s,e)=>ResumeSale();Controls.AddRange(new Control[]{h,scan,add,scanner,cart,remove,total,pay,hold,resume});RefreshCart();}void AddToCart(){string s=scan.Text.Trim();if(s.Contains("..."))return;var m=AppStore.Medicines.FirstOrDefault(x=>x.Barcode==s||x.NameFa.IndexOf(s,StringComparison.OrdinalIgnoreCase)>=0||x.NameEn.IndexOf(s,StringComparison.OrdinalIgnoreCase)>=0);if(m==null){MessageBox.Show(Localization.Persian?"دارو پیدا نشد.":"Medicine not found.");return;}if(m.Stock<=0){MessageBox.Show(Localization.Persian?"موجودی این دارو صفر است.":"This medicine is out of stock.");return;}var line=lines.FirstOrDefault(x=>x.Medicine.Id==m.Id);if(line==null)lines.Add(new SaleLine{Medicine=m,Quantity=1});else if(line.Quantity<m.Stock)line.Quantity++;scan.Clear();RefreshCart();}void Remove(){if(cart.CurrentRow==null)return;int id=Convert.ToInt32(cart.CurrentRow.Cells["Id"].Value);lines.RemoveAll(x=>x.Medicine.Id==id);RefreshCart();}void RefreshCart(){cart.DataSource=null;cart.DataSource=lines.Select(x=>new{Id=x.Medicine.Id,Medicine=Localization.Persian?x.Medicine.NameFa:x.Medicine.NameEn,Qty=x.Quantity,UnitPrice=x.Medicine.SellPrice,Total=x.Total}).ToList();decimal t=lines.Sum(x=>x.Total);total.Text=(Localization.Persian?"جمع کل\n":"Total\n")+t.ToString("N0")+(Localization.Persian?" ریال":" IRR");}void Checkout(){if(lines.Count==0)return;decimal subtotal=lines.Sum(x=>x.Total);using(var payment=new PaymentForm(subtotal)){if(payment.ShowDialog(this)!=DialogResult.OK)return;lastPayment=payment.Result;}var receiptLines=lines.Select(x=>new SaleLine{Medicine=x.Medicine,Quantity=x.Quantity}).ToList();try{int id;if(AppStore.PersistentMode){id=SaleRepository.Create(lines,Localization.Persian?"مشتری حضوری":"Walk-in customer");foreach(var x in lines)x.Medicine.Stock-=x.Quantity;AuditRepository.Log("Create","Sale","Sale #"+id);}else{foreach(var x in lines)x.Medicine.Stock-=x.Quantity;id=AppStore.Sales.Count+1;}AppStore.Sales.Add(new SaleTransaction{Id=id,CreatedAt=DateTime.Now,Total=lines.Sum(x=>x.Total),Customer=Localization.Persian?"مشتری حضوری":"Walk-in customer",Status="Completed"});if(AppStore.PersistentMode){PaymentRepository.Save(id,lastPayment);AuditService.Write(Session.CurrentUser==null?"system":Session.CurrentUser.Username,"Checkout","Sale","Sale #"+id+" / "+lastPayment.Method);}MessageBox.Show(Localization.Persian?"فروش با موفقیت ثبت شد.":"Sale completed successfully.");var receipt=ReceiptBuilder.Build(id,receiptLines,lastPayment);using(var preview=new ReceiptPreviewForm(receipt))preview.ShowDialog(this);lines.Clear();RefreshCart();}catch(Exception ex){MessageBox.Show((Localization.Persian?"ثبت فروش ناموفق بود: ":"Sale failed: ")+ex.Message);}}void HoldSale(){if(lines.Count==0)return;HeldSaleService.Hold(lines,Localization.Persian?"فروش صندوق":"Counter sale");lines.Clear();RefreshCart();MessageBox.Show(Localization.Persian?"فروش معلق شد.":"Sale held.");}void ResumeSale(){using(var f=new HeldSalesForm()){if(f.ShowDialog(this)!=DialogResult.OK||f.SelectedSale==null)return;lines=f.SelectedSale.Lines;RefreshCart();}}}}
